"""Run in Unreal Editor 5.7 Python after compiling the project module."""
import unreal

path = "/Game/Maps/Prototype"
if unreal.EditorAssetLibrary.does_asset_exist(path):
    unreal.log("Prototype map already exists; preserving it.")
else:
    subsystem = unreal.get_editor_subsystem(unreal.LevelEditorSubsystem)
    if not subsystem.new_level(path):
        raise RuntimeError("Could not create prototype map")
    # Geometry, lights and starts are generated by the native game mode at runtime.
    if not subsystem.save_current_level():
        raise RuntimeError("Could not save prototype map")
    unreal.log("Created " + path)
